"""V2 regression tests: factual map, separate planning, offline and mobile."""
from pathlib import Path
import json,html,csv,io,hashlib,os
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1]
report={'version':2,'errors':[],'checks':[]}
def check(condition,label):
    assert condition,label
    report['checks'].append(label)
def downloaded_rows(download):
    return list(csv.DictReader(io.StringIO(Path(download.path()).read_text(encoding='utf-8-sig'))))
original=json.loads((ROOT/'tests/timetable-fingerprint.json').read_text())['sha256']
network=json.loads((ROOT/'data/network.json').read_text())
fingerprint=hashlib.sha256(json.dumps([(r['id'],r['historic'],r['current']) for r in network['routes']],sort_keys=True,separators=(',',':')).encode()).hexdigest()
check(fingerprint==original,'Route data match the independently audited baseline')
audit=json.loads((ROOT/'accuracy-check/independent-audit.json').read_text())
check(audit['result']=='pass','Independent raw-GTFS and PDF audit has no remaining discrepancies')
geo=hashlib.sha256(json.dumps([(r['id'],(r['historic'] or {}).get('paths'),(r['current'] or {}).get('paths')) for r in network['routes']],sort_keys=True,separators=(',',':')).encode()).hexdigest()
check(geo==json.loads((ROOT/'tests/timetable-fingerprint.json').read_text())['geometry_sha256'],'Original route geometry is unchanged by the accuracy corrections')
