    check(page.locator('.brand').get_attribute('aria-label')=='Santa Barbara Transit Atlas, home' and 'Santa Barbara' in page.locator('.brand').inner_text(),'Visible branding and the accessible home label use the new name')
    check(page.locator('.intro h1').inner_text()=='Routes and frequency','Network heading is descriptive rather than a slogan')
    banned=['South Coast Transit Atlas','Same coast.','Less service.','Keep the buses useful.','Fix the funding.','Keep the busy buses.','Make overlaps work.','Find the quiet trips.','Replace the temporary money.']
